// EDIT ME: same list must also be edited in the "Config" node of the poll branch below.
const watchedGroups = [
  { chatId: "120363012345678901@g.us", label: "\u05dc\u05e7\u05d5\u05d7\u05d5\u05ea VIP" },
  { chatId: "120363019876543210@g.us", label: "\u05e7\u05d1\u05d5\u05e6\u05ea \u05ea\u05de\u05d9\u05db\u05d4" }
];
return items.map(item => ({ json: { ...item.json, watchedGroups } }));

const staticData = $getWorkflowStaticData('global');
staticData.knownMembers = staticData.knownMembers || {};

const output = [];
for (const item of items) {
  const watchedGroups = item.json.watchedGroups;
  const sd = item.json.body && item.json.body.senderData;
  if (!sd) continue;
  const group = watchedGroups.find(g => g.chatId === sd.chatId);
  if (!group) continue;

  const known = new Set(staticData.knownMembers[group.chatId] || []);
  if (known.has(sd.sender)) continue;

  const rawPhone = sd.sender.split('@')[0];
  const displayName = sd.senderName || sd.senderContactName || '';
  const parts = displayName.split(' ').filter(Boolean);

  output.push({ json: {
    rawPhone,
    groupLabel: group.label,
    chatId: group.chatId,
    sender: sd.sender,
    firstName: parts[0] || '',
    lastName: parts.slice(1).join(' ') || ''
  }});
}
return output;

const matched = $('Match group and dedup').item.json;
const staticData = $getWorkflowStaticData('global');
staticData.knownMembers = staticData.knownMembers || {};
staticData.knownMembers[matched.chatId] = staticData.knownMembers[matched.chatId] || [];
if (!staticData.knownMembers[matched.chatId].includes(matched.sender)) {
  staticData.knownMembers[matched.chatId].push(matched.sender);
}
return $input.item;

// EDIT ME: same list must also be edited in the "Config" node of the webhook branch above.
const watchedGroups = [
  { chatId: "120363012345678901@g.us", label: "\u05dc\u05e7\u05d5\u05d7\u05d5\u05ea VIP" },
  { chatId: "120363019876543210@g.us", label: "\u05e7\u05d1\u05d5\u05e6\u05ea \u05ea\u05de\u05d9\u05db\u05d4" }
];
const greenApi = {
  idInstance: "REPLACE_ME",
  tokenInstance: "REPLACE_ME",
  baseUrl: "https://api.greenapi.com"
};
return watchedGroups.map(g => ({ json: { chatId: g.chatId, label: g.label, greenApi } }));

const group = $('Config (poll branch)').item.json;
const response = $json;
const currentMembers = (response.participants || []).map(p => p.id);

const staticData = $getWorkflowStaticData('global');
staticData.knownMembers = staticData.knownMembers || {};
const known = new Set(staticData.knownMembers[group.chatId] || []);
const newMembers = currentMembers.filter(id => !known.has(id));
staticData.knownMembers[group.chatId] = currentMembers;

return { json: { chatId: group.chatId, label: group.label, greenApi: group.greenApi, newMembers } };

const output = [];
for (const item of items) {
  const { chatId, label, greenApi, newMembers } = item.json;
  for (const memberId of newMembers) {
    output.push({ json: { chatId, label, greenApi, memberId, rawPhone: memberId.split('@')[0] } });
  }
}
return output;

const original = $('Explode new members').item.json;
const info = $json || {};
const displayName = info.name || '';
const parts = displayName.split(' ').filter(Boolean);
return { json: {
  rawPhone: original.rawPhone,
  groupLabel: original.label,
  firstName: parts[0] || '',
  lastName: parts.slice(1).join(' ') || ''
}};
